def compute_gtk(p_skey: str) -> int:
    """Compute the g_tk (anti-CSRF) token from p_skey cookie."""
    h = 5381
    for ch in p_skey:
        h += (h << 5) + ord(ch)
    return h & 0x7FFFFFFF

